-- Staged search-eval candidates generated by offline Mastra workflows.
--
-- Generated rows are not durable regression truth. Trace-derived candidates
-- carry retention_expires_at so raw trace text does not outlive the raw trace
-- retention policy before a future human-promotion workflow takes ownership.

CREATE TYPE "SearchEvalCandidateSource" AS ENUM (
  'catalog',
  'locale_quality',
  'trace'
);

CREATE TYPE "SearchEvalCandidatePromotionStatus" AS ENUM (
  'generated',
  'rejected',
  'promoted'
);

CREATE TABLE "search_eval_candidate" (
  "id" text NOT NULL,
  "source" "SearchEvalCandidateSource" NOT NULL,
  "locale" varchar(32) NOT NULL,
  "query_text" varchar(512) NOT NULL,
  "expected_result_hints" jsonb NOT NULL DEFAULT '[]',
  "source_anchors" jsonb NOT NULL DEFAULT '[]',
  "label_provenance" jsonb NOT NULL DEFAULT '{}',
  "generation_model" varchar(128) NOT NULL,
  "generation_provider" varchar(64),
  "judge_summary" jsonb,
  "promotion_status" "SearchEvalCandidatePromotionStatus" NOT NULL DEFAULT 'generated',
  "mastra_run_id" varchar(128),
  "dedupe_key" varchar(64) NOT NULL,
  "retention_expires_at" timestamp(3),
  "generated_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "created_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp(3) NOT NULL,

  CONSTRAINT "search_eval_candidate_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "search_eval_candidate_dedupe_key_key"
  ON "search_eval_candidate"("dedupe_key");

CREATE INDEX "search_eval_candidate_source_locale_created_at_idx"
  ON "search_eval_candidate"("source", "locale", "created_at");

CREATE INDEX "search_eval_candidate_promotion_status_created_at_idx"
  ON "search_eval_candidate"("promotion_status", "created_at");

CREATE INDEX "search_eval_candidate_retention_expires_at_idx"
  ON "search_eval_candidate"("retention_expires_at");

CREATE INDEX "search_eval_candidate_mastra_run_id_idx"
  ON "search_eval_candidate"("mastra_run_id");
